    "chunker_version",
    "configuration_digest",
    "contract_version",
    "embedding_dimensions",
    "embedding_model_id",
    "embedding_provider_id",
    "engine_version",
    "lexical_backend",
    "policy_digest",
    "projection_digest",
    "projection_id",
